import { describe, it, expect } from 'vitest';
import { mockSupabase } from './mocks';
import { appendChangeLog } from '../repo';

describe('appendChangeLog', () => {
  beforeEach(() => {
    mockSupabase();
  });

  it('should insert without explicit id', async () => {
    const spy = jest.spyOn(mockSupabase().from('changelog').insert, 'calledWith');
    await appendChangeLog({ campaign_id: '1', user_id: '2', action: 'test' });
    expect(spy).toHaveBeenCalledWith(expect.arrayContaining([expect.objectContaining({ id: expect.anything(), campaign_id: '1', user_id: '2', action: 'test' })]));
  });

  it('should propagate insert errors', async () => {
    const spy = jest.spyOn(mockSupabase().from('changelog').insert, 'throwError');
    await expect(appendChangeLog({ campaign_id: '1', user_id: '2', action: 'test' })).rejects.toThrow();
  });
});

